def ph(f, pos='50% 20%'):
    if f.endswith('.HEIC'):
        return {'photos': ['file:///D:/yulia_zavod_syrye/karuseli_nedeli/foto/' + f[:-5] + '.jpg'], 'photoPos': pos}
    return {'photos': [B + f], 'photoPos': pos}


def P(f, kicker, title, text, b, a, pos='50% 20%', scale=None):
    s = {'role': 'photo', **ph(f, pos), 'kicker': kicker, 'title': title, 'text': text,
         'before': {'label': b[0], 'text': b[1]}, 'after': {'label': a[0], 'text': a[1]}}
    if scale:
        s['textScale'] = scale
    return s


def cover(f, badge, title, lead, pos='50% 25%'):
    return {'role': 'cover', **ph(f, pos), 'badge': badge, 'title': title, 'lead': lead, 'textScale': 0.62}


